WITH ev_f AS (SELECT 1 AS id, 'apple' AS s, 1.0 AS n, DATE '2026-12-31' AS d, TIMESTAMP '2026-12-31 23:30:00' AS ts, TRUE AS y UNION ALL
      SELECT 2, 'Apple', 5.0, DATE '2027-01-03', TIMESTAMP '2027-01-03 10:00:00', FALSE UNION ALL
      SELECT 3, 'banana', 7.0, DATE '2026-03-01', TIMESTAMP '2026-03-01 12:00:00', CAST(NULL AS BOOL) UNION ALL
      SELECT 4, '', -5.0, DATE '2026-04-01', TIMESTAMP '2026-04-01 00:00:00', TRUE UNION ALL
      SELECT 5, 'a,b', 10.0, DATE '2026-12-01', TIMESTAMP '2026-12-01 08:00:00', FALSE UNION ALL
      SELECT 6, 'pineapple', 2.5, DATE '2027-01-04', TIMESTAMP '2027-01-04 00:15:00', FALSE UNION ALL
      SELECT 7, CAST(NULL AS STRING), CAST(NULL AS FLOAT64), CAST(NULL AS DATE), CAST(NULL AS TIMESTAMP), CAST(NULL AS BOOL) )
SELECT
    (CASE WHEN ev_f.n > 3  THEN 'Yes' ELSE 'No' END) AS ev_f_n_big,
    COUNT(*) AS ev_f_count,
    CASE WHEN COUNT(ev_f.n ) <= 10000 THEN (ARRAY_AGG(ev_f.n  IGNORE NULLS ORDER BY ev_f.n  LIMIT 10000)[OFFSET(CAST(FLOOR(COUNT(ev_f.n ) * 0.5 - 0.0000001) AS INT64))] + ARRAY_AGG(ev_f.n  IGNORE NULLS ORDER BY ev_f.n  LIMIT 10000)[OFFSET(CAST(FLOOR(COUNT(ev_f.n ) * 0.5) AS INT64))]) / 2 ELSE APPROX_QUANTILES(ev_f.n ,1000)[OFFSET(500)] END AS ev_f_n_median,
    CASE WHEN COUNT(ev_f.n ) <= 10000 THEN (ARRAY_AGG(ev_f.n  IGNORE NULLS ORDER BY ev_f.n  LIMIT 10000)[OFFSET(CAST(FLOOR(COUNT(ev_f.n ) * 0.25 - 0.0000001) AS INT64))] + ARRAY_AGG(ev_f.n  IGNORE NULLS ORDER BY ev_f.n  LIMIT 10000)[OFFSET(CAST(FLOOR(COUNT(ev_f.n ) * 0.25) AS INT64))]) / 2 ELSE APPROX_QUANTILES(ev_f.n ,1000)[OFFSET(250)] END AS ev_f_n_p25,
    CASE WHEN COUNT(ev_f.n ) <= 10000 THEN (ARRAY_AGG(ev_f.n  IGNORE NULLS ORDER BY ev_f.n  LIMIT 10000)[OFFSET(CAST(FLOOR(COUNT(ev_f.n ) * 0.9 - 0.0000001) AS INT64))] + ARRAY_AGG(ev_f.n  IGNORE NULLS ORDER BY ev_f.n  LIMIT 10000)[OFFSET(CAST(FLOOR(COUNT(ev_f.n ) * 0.9) AS INT64))]) / 2 ELSE APPROX_QUANTILES(ev_f.n ,1000)[OFFSET(900)] END AS ev_f_n_p90,
    COUNT(DISTINCT ev_f.s ) AS ev_f_s_distinct,
    COALESCE(SUM(ev_f.n ), 0) AS ev_f_n_sum,
    AVG(ev_f.n ) AS ev_f_n_avg,
    MIN(ev_f.n ) AS ev_f_n_min,
    MAX(ev_f.d ) AS ev_f_n_max_date,
        COALESCE(SUM(ev_f.n ), 0) / NULLIF(COUNT(*), 0) AS ev_f_n_per_row,
    COALESCE(SUM(CASE WHEN ev_f.n > 3  THEN ev_f.n  ELSE NULL END), 0) AS ev_f_n_sum_big
FROM ev_f
GROUP BY
    1
ORDER BY
    1
LIMIT 500
